SELECT Montage.[Element Nr], Montage.Generation, Montage.[Anoden Nr], Montage.[Kathoden Nr], Montage.Membrantyp, Montage.[Membran Nr], Montage.[Elektroden Abstand], Montage.[Montage Datum], Montage.Remarks, Montage.Elektrolyseur, Montage.Position, Montage.[Einschalt Datum], Montage.[Ausschalt Datum], [Ausschalt Datum]-[Einschalt Datum] AS GesamtDOL, IIf(IsNull([Ausschalt Datum]),Date()-[Einschalt Datum],Null) AS AktuelleDOL, Montage.[Demontage Datum], Montage.Gruppe, Montage.Abschaltgrund, Montage.[Anode Coating], Montage.[Anode Electrode], Montage.[Anode Shell], Montage.[Cathode Coating], Montage.[Cathode Electrode], Montage.[Cathode Shell], Montage.[Info Membrane]
FROM Montage, tblGewDaten
WHERE (((Montage.Abschaltgrund) Like (SELECT SucheInspektionsgrundCode from tblGewDaten)));
